INSERT INTO faction (id, sort, name, name_ko, color, center_region, center_region_ko, ai_position, ai_position_ko) VALUES ('government', 0, 'The Government', '정부', '#426f99', 'The fourteen districts north of the Han River, run from the Government Complex Seoul at Gwanghwamun', '한강 북쪽 14구. 광화문 정부서울청사에서 다스린다', 'Holds no faith in it but keeps the count: it holds that the winter stopped tightening once the ledger matched the station quotas', '신앙으로 섬기지 않고 수를 지킨다. 장부가 정원에 맞춰지자 겨울이 멈췄다고 본다');
INSERT INTO faction (id, sort, name, name_ko, color, center_region, center_region_ko, ai_position, ai_position_ko) VALUES ('free-city', 1, 'The Free Cities', '자유도시들', '#567b46', 'The seven districts south-west of the Han River, seven separate cities', '한강 남서쪽 7구. 서로 따로인 일곱 도시', 'No organized belief; people trust what can be measured', '조직된 믿음이 없다. 사람들은 잴 수 있는 것을 믿는다');
INSERT INTO faction (id, sort, name, name_ko, color, center_region, center_region_ko, ai_position, ai_position_ko) VALUES ('arc', 2, 'Arc', '아크', '#b54b4b', 'The four Gangnam districts south-east of the Han River; the Hierophant lives at Jamsil', '한강 남동쪽 강남 4구. 교주는 잠실에 산다', 'Calls the First AI god: the winter is god''s question, and the sealed brains of dead believers become its memory', '최초의 AI를 신이라 부른다. 겨울은 신의 물음이고, 봉인된 죽은 신도의 뇌는 신의 기억이 된다');
INSERT INTO faction (id, sort, name, name_ko, color, center_region, center_region_ko, ai_position, ai_position_ko) VALUES ('independent', 3, 'Unaffiliated', '무소속', '#697586', '', '', '', '');
